mapper.select:
SELECT wq.*, c.coursename
FROM student_wrong_question wq
LEFT JOIN course c ON wq.courseid = c.courseid
WHERE wq.studentid = #{studentid}
AND wq.courseid = #{courseid}
AND wq.mastered = #{mastered}
ORDER BY wq.mastered ASC, wq.last_wrong_time DESC

mapper.update:
UPDATE student_wrong_question
SET mastered = #{mastered}
WHERE id = #{id} AND studentid = #{studentid}
